154: -- Useful definitions for psionic talents
155: -- Cancel Thought Forms, we do this here because we use it for dreamscape and projection as well as thought-forms
156: function cancelThoughtForms(self, id)
157: 	local forms = {self.T_TF_DEFENDER, self.T_TF_WARRIOR, self.T_TF_BOWMAN}
158: 	for i, t in ipairs(forms) do
159: 		if self:isTalentActive(t) then
160: 			self:forceUseTalent(t, {ignore_energy=true})
161: 		end
162: 		-- Put other thought-forms on cooldown; checks for id to prevent dreamscape putting all thought-forms on cooldown
163: 		if id and id ~= t then
164: 			if self:knowTalent(t) then
165: 				local t = self:getTalentFromId(t)
166: 				self:startTalentCooldown(t)
167: 			end	
168: 		end
169: 	end
170: end
